func lookup[T](value: uint32, ranges: openArray[T], fallback: auto): auto =
  var low = 0
  var high = ranges.len
  while low < high:
    let middle = (low + high) shr 1
    if value < ranges[middle].lo: high = middle
    elif value > ranges[middle].hi: low = middle + 1
    else: return ranges[middle].value
  fallback

func inRanges(value: uint32, ranges: openArray[UnicodeRange]): bool =
  var low = 0
  var high = ranges.len
  while low < high:
    let middle = (low + high) shr 1
    if value < ranges[middle].lo: high = middle
    elif value > ranges[middle].hi: low = middle + 1
    else: return true
  false

func graphemeBreak*(value: uint32): GraphemeBreak =
  lookup(value, graphemeRanges, gbOther)

func eastAsianWidth*(value: uint32): EastAsianWidth =
  lookup(value, widthRanges, eawNeutral)

func indicConjunctBreak*(value: uint32): IndicConjunctBreak =
  lookup(value, indicRanges, incbNone)

func isExtendedPictographic*(value: uint32): bool =
  inRanges(value, extendedPictographicRanges)
